def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    priority_scores = np.full_like(bins, -np.inf)
    fits = remaining >= 0
    if fits.any():
        remaining_fits = remaining[fits]
        exact = remaining_fits == 0
        if exact.any():
            priority_scores[fits] = np.where(exact, 1, 0)
        else:
            priority_scores[fits] = 1 / (remaining_fits + 1)
    return priority_scores
